timeout 180 node --experimental-vm-modules node_modules/jest/bin/jest.js --coverage --coverageReporters=json-summary 2>&1 | grep -E "(threshold|Threshold)" && node --input-type=module -e "
import {readFileSync} from 'node:fs';
const data = JSON.parse(readFileSync('coverage/coverage-summary.json', 'utf8'));
const key = Object.keys(data).find(k => k.includes('orchestration/tools/registry.ts'));
console.log(JSON.stringify(data[key]));
const orchKeys = Object.keys(data).filter(k => k.includes('orchestration'));
let total = 0, covered = 0;
for (const k of orchKeys) { total += data[k].branches.total; covered += data[k].branches.covered; }
console.log('orchestration total:', total, 'covered:', covered, 'pct:', (covered/total*100).toFixed(2));
"

timeout 180 node --experimental-vm-modules node_modules/jest/bin/jest.js --coverage --coverageReporters=json 2>&1 | tail -5 && node --input-type=module -e "
import {readFileSync} from 'node:fs';
const data = JSON.parse(readFileSync('coverage/coverage-final.json', 'utf8'));
const key = Object.keys(data).find(k => k.includes('orchestration/tools/registry.ts'));
const file = data[key];
const branchMap = file.branchMap;
const branches = file.b;
for (const id of Object.keys(branchMap)) {
  const bm = branchMap[id];
  const b = branches[id];
  const uncovered = b.map((n,i) => n === 0 ? i : null).filter(x => x !== null);
  if (uncovered.length > 0) {
    console.log('Line', bm.loc.start.line, bm.type, '->', uncovered.map(i => 'branch' + i + '=0').join(', '));
  }
}
"
